//| Event lifecycle                                                  |
//+------------------------------------------------------------------+
void
OpenEvent(
const
int
dir,
const
MqlRates
&b,
const
int
shift,
const
double
level)
  {
   BreakEvent e;
ZeroMemory
(e);

   e.active         =
true
;
   e.id             = ++g_eventSeq;
   e.dir            = dir;
   e.rng            = g_range;
   e.brkTime        = b.time;
   e.brkOpen        = b.open;
   e.brkHigh        = b.high;
   e.brkLow         = b.low;
   e.brkClose       = b.close;
