true
;
else
g_range.brokeDown =
true
;
if
(InpVerbose)
PrintFormat
(
"Breakout #%d %s at %s  price=%s  volRatio=%.2f"
,
                  e.id, (dir >
0
?
"UP"
:
"DOWN"
